    if now is None:
        now = time.time()
    if not os.path.isdir(dir):
        return 0

    removed = 0
    try:
        with os.scandir(dir) as entries:
            for entry in entries:
                try:
                    if entry.is_file():
                        if (now - entry.stat().st_mtime) > max_age_s:
                            os.remove(entry.path)
                            removed += 1
                except OSError:
                    continue
    except OSError:
        return 0

    return removed
